  this.scene.add(new THREE.HemisphereLight(0xffffff,0xa2a597,2.6));const sun=new THREE.DirectionalLight(0xfff9e8,3.5);sun.position.set(-500,850,300);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.bias=-.0005;sun.shadow.normalBias=.8;this.scene.add(sun);this.sun=sun;
