  const nodeHeights=new Map(net.nodes.map(n=>[n.id,1]));if(u==='electric'){for(const e of net.edges)if(e.placement==='overhead'){for(const id of [e.from,e.to]){const n=nodes.get(id);if(n.kind!=='meter'&&n.kind!=='transformer')nodeHeights.set(id,10);}}}
