 cylinders(segments,color,opacity=1){let m=this.instances(new THREE.CylinderGeometry(1,1,1,5),new THREE.MeshBasicMaterial({color,transparent:opacity<1,opacity,depthWrite:false}),segments.length);m.castShadow=false;m.receiveShadow=false;const up=new THREE.Vector3(0,1,0);for(let i=0;i<segments.length;i++){const {a,b,r}=segments[i],mid=a.clone().add(b).multiplyScalar(.5),d=b.clone().sub(a);dummy.position.copy(mid);dummy.quaternion.setFromUnitVectors(up,d.clone().normalize());dummy.scale.set(r,d.length(),r);dummy.updateMatrix();m.setMatrixAt(i,dummy.matrix);}m.instanceMatrix.needsUpdate=true;m.computeBoundingSphere();return m;}
 drawStations(){for(const u of UTILS){const net=this.town.networks[u],n=net.nodes.find(n=>n.id===net.stationId),y=terrain(n.x,n.z);this.box(28,.4,26,'#d6d9cc',n.x,y,n.z);this.box(12,5.5,10,'#edece2',n.x,y+2.8,n.z);this.box(13,1,11,'#a0aca5',n.x,y+6,n.z);if(u==='water'){for(let k=-1;k<=1;k+=2){const tank=new THREE.Mesh(new THREE.CylinderGeometry(4.7,4.7,8,18),material('#dfe4db'));tank.position.set(n.x+9,y+4,n.z+k*6);tank.castShadow=true;this.root.add(tank);}}else if(u==='electric'){for(let k=-1;k<=1;k+=2){this.box(3,6,4,'#899990',n.x+10,y+3,n.z+k*6);}}else{this.box(4,3,15,'#bac3b8',n.x+10,y+1.6,n.z);}
  const el=document.createElement('button');el.className=`map-label ${u}`;el.innerHTML=`<span class="label-dot"></span>${n.label}`;el.setAttribute('aria-label',`Inspect ${n.label}`);el.onclick=()=>this.onSelect({asset:u});this.el.append(el);this.markers.push({el,position:new THREE.Vector3(n.x,y+12,n.z)});
 }}
 setLayers(layers){this.layers={...layers};if(!this.networkGroups)return;for(const u of UTILS){this.networkGroups[u].visible=!!layers[u];this.serviceGroups[u].visible=!!layers[u]&&this.xray;this.particleGroups[u].mesh.visible=!!layers[u];}this.markers.forEach(m=>{m.el.style.opacity='1';});}
