  this.renderer.render(this.scene,this.camera);for(const m of this.markers){const p=m.position.clone().project(this.camera);m.el.style.transform=`translate(-50%,-100%) translate(${(p.x*.5+.5)*this.el.clientWidth}px,${(-p.y*.5+.5)*this.el.clientHeight}px)`;m.el.style.display=p.z>1||Math.abs(p.x)>1.2||Math.abs(p.y)>1.2?'none':'';}this.frame++;
